import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeEndArray
 */
public class TokenBuffer_writeEndArray_TriageGen2Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteEndArray_RootLevel() throws IOException {
        // Test behavior when there is no parent context (root level)
        // The implementation says: if (c != null) { _writeContext = c; }
        // If c is null, _writeContext remains the same (the root context)

        tokenBuffer.writeEndArray();

        // Verify that the token appended is END_ARRAY
        // We use asParser to inspect the buffer contents
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parser.nextToken());
    }

    @Test
    public void testWriteEndArray_WithNestedContext() throws IOException {
        // Test behavior when there is a parent context (nested level)
        // This exercises the branch: if (c != null) { _writeContext = c; }

        tokenBuffer.writeStartArray(); // Enter array context
        tokenBuffer.writeNumber(1);

        // Verify we are currently inside an array
        JsonParser parserBefore = tokenBuffer.asParser();
        parserBefore.nextToken(); // START_ARRAY
        parserBefore.nextToken(); // NUMBER 1

        tokenBuffer.writeEndArray(); // This should move the context to the parent

        // To verify the context movement, we check if we can write a new structure 
        // that belongs to the parent scope.
        tokenBuffer.writeStartObject();
        tokenBuffer.writeFieldName("test");
        tokenBuffer.writeString("value");
        tokenBuffer.writeEndObject();

        // Serialize to a generator to verify the full JSON structure
        // If context didn't move up, the JSON would be invalid or incorrectly nested
        tokenBuffer.serialize(new JsonGeneratorStub());

        // Instead of a complex stub, let's verify via the parser sequence
        JsonParser parserAfter = tokenBuffer.asParser();
        assertEquals(JsonToken.START_ARRAY, parserAfter.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserAfter.nextToken());
        assertEquals(JsonToken.END_ARRAY, parserAfter.nextToken());
        assertEquals(JsonToken.START_OBJECT, parserAfter.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserAfter.nextToken());
        assertEquals("test", parserAfter.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parserAfter.nextToken());
        assertEquals(JsonToken.END_OBJECT, parserAfter.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parserAfter.nextToken());
    }

    @Test
    public void testWriteEndArray_DeeplyNested() throws IOException {
        // Test multiple levels of nesting to ensure context moves up correctly multiple times
        tokenBuffer.writeStartObject();    // Level 0: Object
            tokenBuffer.writeStartArray(); // Level 1: Array
                tokenBuffer.writeStartArray(); // Level 2: Array
                    tokenBuffer.writeNumber(42);
                tokenBuffer.writeEndArray();   // Move context to Level 1
            tokenBuffer.writeEndArray();       // Move context to Level 0
        tokenBuffer.writeEndObject();          // Close Level 0

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parser.nextToken());
    }

    /**
     * A simple stub to satisfy the serialize method signature if needed for verification.
     */
    private static class JsonGeneratorStub extends com.fasterxml.jackson.core.JsonGenerator {
        protected JsonGeneratorStub() {
            super(null, null);
        }
        @Override public void writeString(String t) throws IOException {}
        @Override public void writeNumber(int v) throws IOException {}
        // Other methods are not needed for this specific test logic
    }
}
